CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL CHECK(email=lower(email)), role text NOT NULL CHECK(role IN ('candidate','employer','reviewer')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid UNIQUE NOT NULL REFERENCES users(id), data jsonb NOT NULL DEFAULT '{}', revision int NOT NULL DEFAULT 1 CHECK(revision>=1), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, csrf_token text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', revoked_at timestamptz);
CREATE TABLE otp_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, role text NOT NULL, code_hash text NOT NULL, ip_hash text NOT NULL, attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes', invalidated_at timestamptz, verified_session_id uuid REFERENCES sessions(id));
CREATE INDEX otp_email_date ON otp_challenges(email,created_at);
CREATE INDEX otp_ip_date ON otp_challenges(ip_hash,created_at);
CREATE TABLE resumes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid UNIQUE NOT NULL REFERENCES users(id), data jsonb NOT NULL DEFAULT '{}', publication_state text NOT NULL DEFAULT 'draft' CHECK(publication_state IN ('draft','published','hidden')), revision int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE self_assessments(owner_id uuid PRIMARY KEY REFERENCES users(id), data jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'not_started', revision int NOT NULL DEFAULT 1);
CREATE TABLE program_blocks(owner_id uuid NOT NULL REFERENCES users(id), block text NOT NULL CHECK(block IN ('professional','cognitive')), state text NOT NULL DEFAULT 'not_started', PRIMARY KEY(owner_id,block));
CREATE TABLE consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, version text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bank_versions(version text PRIMARY KEY, data jsonb NOT NULL, checksum text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), specialization text NOT NULL DEFAULT 'Backend', target_grade text NOT NULL CHECK(target_grade IN ('Junior','Middle')), state text NOT NULL DEFAULT 'answering_B', resume_state text, bank_version text NOT NULL REFERENCES bank_versions(version), rubric_version text NOT NULL, scoring_version text NOT NULL, adaptation_status text NOT NULL DEFAULT 'final', started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', finalized_at timestamptz, review_started_at timestamptz, outcome text, revision int NOT NULL DEFAULT 1, result jsonb);
CREATE UNIQUE INDEX one_active_attempt ON attempts(owner_id,specialization) WHERE state NOT IN ('finalized','expired');
CREATE TABLE attempt_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES attempts(id), ordinal int NOT NULL CHECK(ordinal BETWEEN 1 AND 20), stage text NOT NULL CHECK(stage IN ('B','A','V')), item_id text NOT NULL, private_item jsonb NOT NULL, selection jsonb NOT NULL DEFAULT '{}', draft text, draft_revision int NOT NULL DEFAULT 1, answer text, submitted_at timestamptz, deferred boolean NOT NULL DEFAULT false, score int CHECK(score BETWEEN 0 AND 4), criteria jsonb, evaluation_source text, evaluation_revision int NOT NULL DEFAULT 1, UNIQUE(attempt_id,ordinal));
CREATE TABLE review_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES attempt_tasks(id), attempt_id uuid NOT NULL REFERENCES attempts(id), reviewer_id uuid NOT NULL REFERENCES users(id), criteria jsonb, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), attempt_id uuid UNIQUE REFERENCES attempts(id), grade text NOT NULL CHECK(grade IN ('Junior','Middle')), score numeric(6,3) NOT NULL CHECK(score BETWEEN 0 AND 100), verified_at timestamptz NOT NULL DEFAULT now(), source text NOT NULL DEFAULT 'assessment', synthetic boolean NOT NULL DEFAULT false);
CREATE TABLE cognitive_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), state text NOT NULL DEFAULT 'in_progress', version text NOT NULL REFERENCES bank_versions(version), answered_count int NOT NULL DEFAULT 0 CHECK(answered_count BETWEEN 0 AND 6), feedback jsonb, revision int NOT NULL DEFAULT 1, started_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_cognitive ON cognitive_sessions(owner_id) WHERE state!='completed';
CREATE TABLE cognitive_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES cognitive_sessions(id), ordinal int NOT NULL, private_item jsonb NOT NULL, draft text, draft_revision int NOT NULL DEFAULT 1, answer text, correct int CHECK(correct IN (0,1)), opened_at timestamptz, submitted_at timestamptz, UNIQUE(session_id,ordinal));
CREATE TABLE activity_intervals(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES cognitive_tasks(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, CHECK(end_at>=start_at AND end_at<=start_at+interval '30 seconds'));
CREATE TABLE needs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), data jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'draft', revision int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shortlist(company_id uuid REFERENCES companies(id), candidate_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,candidate_id));
CREATE TABLE matching_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), need_id uuid REFERENCES needs(id), formula_version text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), candidate_id uuid NOT NULL REFERENCES users(id), need_id uuid NOT NULL REFERENCES needs(id), data jsonb NOT NULL, state text NOT NULL DEFAULT 'sent', revision int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), viewed_at timestamptz, responded_at timestamptz, delivery_state text NOT NULL DEFAULT 'pending');
CREATE TABLE contact_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), candidate_id uuid NOT NULL REFERENCES users(id), invitation_id uuid NOT NULL REFERENCES invitations(id), granted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, revision int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX active_pair_grant ON contact_grants(company_id,candidate_id) WHERE revoked_at IS NULL;
CREATE TABLE fsp_bindings(owner_id uuid PRIMARY KEY REFERENCES users(id), subject_id text NOT NULL, adapter_mode text NOT NULL DEFAULT 'demo', bound_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fsp_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), source_event_id text NOT NULL, data jsonb NOT NULL, UNIQUE(owner_id,source_event_id));
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, dedupe_key text UNIQUE NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ready_jobs ON jobs(run_at) WHERE status IN ('pending','running');
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dedupe_key text UNIQUE NOT NULL, payload jsonb NOT NULL, invitation_id uuid REFERENCES invitations(id), status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, object_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users(id), endpoint text NOT NULL, key uuid NOT NULL, body_hash text NOT NULL, status int, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,endpoint,key));
CREATE TABLE rate_buckets(scope text NOT NULL, bucket bigint NOT NULL, count int NOT NULL DEFAULT 0, PRIMARY KEY(scope,bucket));
